// TH15 v1.00b Stage 7 Extra Boss8 (nonspell), rank 4 only.
// Source entry: st07bs.ecl.txt:1100-1185. Dependencies:
//   Boss8_at      st07bs.ecl.txt:1187-1217
//   Boss8_pos     st07bs.ecl.txt:1260-1269 (only undocumented enm322(3,0); see report)
//   BossB4        st07bs2.ecl.txt:84-106 (other Boss/MBoss, not this card's attacker)
//   BossItemPhase3 default.ecl.txt:37-49 (drops; omitted by policy)
// Frame map: card frame 0 = segment start; 120-frame opening buffer; source t=0 is
// nominally card frame 120 (the enemy's task first runs one frame later). The source's
// +2/+4 chapter-stat gates are kept as a 4-frame setup delay, so the 4200-frame
// setInterrupt window measured from timerReset ends at card frame 4324.
const TIME_LIMIT: int = 4324;
const OPENING_BUFFER: int = 120;
const TH15_BALL: int = 416;      // source etSprite(0,4,2): type 4, color 2, radius 4
const WAYS: int = 90;            // source Boss8_at(...,90): 90-way, one speed layer
const RING_SPEED: int = 2;       // source speed 2.0; one layer ignores speed 0.2
const LIMIT_X: int = 140;        // source moveLimit(0,128,280,64): x in [-140,140]
const LIMIT_Y0: int = 96;        // source moveLimit y in [96,160]
const LIMIT_Y1: int = 160;
const INNER_X: int = 70;         // source moveRand inner threshold: width/4 = 70
const INNER_Y0: int = 112;       // source moveRand inner y 112..144
const INNER_Y1: int = 144;

// 1190-1197: etNew(0); etSprite(0,4,2); etAim(0,3); etCount(0,90,1);
// etAngle(0,0,0); etSpeed(0,2.0,0.2); two EX records type2 ANIM(a=1) and
// type1048576 BRIGHT(a=1). Both EX records are birth/visual effects and are omitted
// under the approved birth-animation/presentation policy; the radius stays type4=4.
sub boss8_at(count: int) {
    sh_reset(0);
    sh_sprite(0, TH15_BALL, 2);
    sh_aim(0, 0);              // etAim(0,3): fixed-direction ring
    sh_ring(0, 1);
    sh_count(0, WAYS, 1);      // etCount(0,90,1)
    sh_speed(0, RING_SPEED as fx, 0fx); // etSpeed(0,2.0,0.2); M=1 -> first speed
    var d: angle = 0deg;
    for burst in 0..count {
        // 1198/1207: the first four bursts each take a fresh RANDRAD; from the fourth
        // onward 1210 adds E/2 = pi/90 = 32768/90 BAM. The full-circle random base is
        // represented by rand(65536) as angle (same distribution, target RNG differs).
        if burst < 4 {
            d = (rand(65536)) as angle;
        } else {
            d = d + ((32768 / WAYS) as angle);
        }
        sh_angle(0, d, 0deg);  // etAngle(0,%D,0)
        sh_fire(0);            // 1212 etOn(0)
        wait(10);              // 1213
    }
}

// 1201-1215 direction/step state: int slot 0 = next source movement step,
// fx slots 0/1 = the fixed logical unit vector sampled once at moveRand().
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.9fx * (60 - k) / 60; } // 1.9 * (1 - k/60), k=1..60
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    // 1157 moveLimit(0,128,280,64): clamp every movement step.
    if nx < (0 - LIMIT_X) as fx { nx = (0 - LIMIT_X) as fx; }
    if nx > LIMIT_X as fx { nx = LIMIT_X as fx; }
    if ny < LIMIT_Y0 as fx { ny = LIMIT_Y0 as fx; }
    if ny > LIMIT_Y1 as fx { ny = LIMIT_Y1 as fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// 1180 moveRand(60,4,1.9): one fixed direction alpha per call, speed linearly
// decaying to zero over 60 source movement ticks. 1198-1215's direction table is
// the documented moveRand recipe: outer x branches sample +/-pi/3; the central
// branch samples +/-pi/4 plus a WORD%3 side choice; y<112 or y>144 fixes the sign;
// then the +/-pi/2 guard. BAM thresholds are the documented quantized values.
sub begin_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < (0 - INNER_X) as fx {
        a = r / 3;
    } else if $self_x > INNER_X as fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; } // this branch is explicitly normalized
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < INNER_Y0 as fx {
        if a < 0 { a = 0 - a; }
    } else if $self_y > INNER_Y1 as fx {
        if a < 0 { a = 0 - a; }
        a = 0 - a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad (~3277 BAM); nearest documented bounds.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_next_step();
}

sub boss8_move_rand(frames: int) {
    begin_move_rand();
    for i in 0..frames {
        wait(1);
        arm_next_step();
    }
}

async sub boss8() {
    // 1102 setInvuln(180) / shell requirement: the training shell keeps the source
    // enemy invulnerable for the whole segment; 180 would expire during the attack.
    set_invuln(65535);
    // Entry state from Boss() st07bs.ecl.txt:8-39: setHurtbox(40,40) -> r20,
    // setHitbox(48,48) -> r24; spawn is already at movePos(0,128).
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // 1113 +2 setChapter(50) and 1115 +4 unknown569(0) are chapter statistics
    // (omitted); keep their 4-frame setup delay so timerReset's 4200-frame window
    // starts at the intended point.
    wait(2);
    wait(2);
    // 1119 timerReset; 1122 TIMEOUT == 0 -> 1123 etCancel(640). A standalone card
    // starts with an empty field; clear_bullets is the closest public field clear.
    clear_bullets();
    // 1120 killAllAsync: this card has no same-enemy async yet.
    // 1121 enmKillAll: clear other enemies, excluding the caller.
    kill_all_enemies(KILL_SILENT);
    // 1128-1131 spellEnd/funcSet(0)/laserCancel/sounds: standalone nonspell has no
    // previous spell, callback or laser; 1129 funcSet(0) is the no-callback state.
    // 1132-1134 stop old velocity and position interpolation.
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    move_to(0, $self_x, $self_y, EASE_LINEAR);
    // 1142 movePosTime(60,4,-80,128)
    move_to(60, -80fx, 128fx, EASE_QUAD_OUT);
    wait(60);
    // 1144 movePosTime(120,1,-192,-80)
    move_to(120, -192fx, -80fx, EASE_QUAD_IN);
    wait(120);
    // 1146-1152 flags/animations/fog/sounds are presentation or shell state.
    // 1153 movePos(0,128)
    move_to(0, 0fx, 128fx, EASE_LINEAR);
    // 1154 lifeSet(16000) -> spawn hp 16000; shell invulnerability keeps DPS out.
    // 1155 setInterrupt(0,3000,4200,"BossCard8"): the shell phase timer is
    // TIME_LIMIT; the 3000 HP threshold is not reachable in the no-DPS shell.
    // 1156 lifeMarker / 1157 moveLimit: the bar is presentational; the moveLimit
    // bounds are enforced in arm_next_step().
    wait(30);  // 1160-1163
    wait(50);  // 1163-1166
    // 1168 @Boss8_pos() async: its only body is 1264 enm322(3,0), which the shared
    // instruction table marks unknown (待核). No public target equivalent exists;
    // omitted and reported rather than guessed.
    wait(60);  // 1169
    // 1170-1183: %F0 is written and flipped but never read by this card; keep the
    // shared-slot init so the entry state matches. $I0 ramps 6,7,8,9,10 then stays 10.
    var i0: int = 6;
    var f0: fx = 0.017453fx;
    loop {
        boss8_at(i0);          // 1174
        if i0 < 10 { i0 = i0 + 1; } // 1175-1176
        f0 = 0fx - f0;         // 1178
        wait(120);             // 1179
        boss8_move_rand(60);   // 1180 moveRand(60,4,1.9); 1181 wait(60)
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    if global(GVAR_RANK) == RANK_EXTRA {
        _ = spawn_enemy(0fx, 128fx, 16000, 0, 0, 0, boss8);
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    // The source 1121 enmKillAll must not kill the synthetic phase owner; it has no
    // source counterpart and the standalone card creates no other source enemies.
    set_enemy_flag(ENEMY_KILLALL_EXEMPT, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
